        int JobH() { return jobActive ? 46 : 0; }
        int JobPct()
        {
            if (jobTotal <= 0) return jobItemTotal > 0 ? (jobItems * 100) / jobItemTotal : 0;
            int p = (jobDone * 100) / jobTotal;
            if (p > 100) p = 100;
